const ESCAPABLE = new Set(["*", "_", "`", "\\"]);

function isWhitespace(ch) {
	return ch === " " || ch === "\t" || ch === "\n" || ch === "\r" || ch === "\f" || ch === "\v";
}

function isLetterOrDigit(ch) {
	return (ch >= "A" && ch <= "Z") || (ch >= "a" && ch <= "z") || (ch >= "0" && ch <= "9");
}

function escapeHtml(str) {
	let out = "";
	for (const ch of str) {
		if (ch === "&") out += "&amp;";
		else if (ch === "<") out += "&lt;";
		else if (ch === ">") out += "&gt;";
		else out += ch;
	}
	return out;
}

/**
 * Find the closing marker index for an opener of `kind` at `openIdx`,
 * searching only within [start of content, end). Skips escape pairs and
 * complete code spans, so their markers can never be the closer.
 */
function findCloser(text, openIdx, end, kind) {
	let k = openIdx + 1;
	while (k < end) {
		const c = text[k];
		if (c === "\\") {
			if (k + 1 < end && ESCAPABLE.has(text[k + 1])) k += 2;
			else k += 1;
			continue;
		}
		if (c === "`") {
			const m = text.indexOf("`", k + 1);
			if (m !== -1 && m < end && m > k + 1) k = m + 1; // skip complete code span
			else k += 1; // bare or adjacent backticks: plain text
			continue;
		}
		if (c === kind && k > openIdx + 1 && !isWhitespace(text[k - 1])) {
			if (kind === "*") return k;
			if (k + 1 >= end || !isLetterOrDigit(text[k + 1])) return k;
		}
		k += 1;
	}
	return -1;
}

/** Parse the region [start, end) of `text` as markup, returning HTML. */
function parse(text, start, end) {
	let out = "";
	let i = start;
	while (i < end) {
		const c = text[i];
		if (c === "\\") {
			if (i + 1 < end && ESCAPABLE.has(text[i + 1])) {
				out += escapeHtml(text[i + 1]); // escaped marker: plain text, dropped backslash
				i += 2;
			} else {
				out += escapeHtml(c); // plain backslash
				i += 1;
			}
		} else if (c === "`") {
			const j = text.indexOf("`", i + 1);
			if (j !== -1 && j < end && j > i + 1) {
				out += `<code>${escapeHtml(text.slice(i + 1, j))}</code>`;
				i = j + 1;
			} else {
				out += "`"; // no later backtick, or empty span: plain text
				i += 1;
			}
		} else if (c === "*" || c === "_") {
			const canOpen =
				i + 1 < end &&
				!isWhitespace(text[i + 1]) &&
				(c !== "_" || i === 0 || !isLetterOrDigit(text[i - 1]));
			const closer = canOpen ? findCloser(text, i, end, c) : -1;
			if (closer === -1) {
				out += escapeHtml(c);
				i += 1;
			} else {
				const tag = c === "*" ? "b" : "i";
				out += `<${tag}>${parse(text, i + 1, closer)}</${tag}>`;
				i = closer + 1;
			}
		} else {
			out += escapeHtml(c);
			i += 1;
		}
	}
	return out;
}

/**
 * Render the markup-lite language as an HTML string.
 * @param {string} text
 * @returns {string}
 */
export function render(text) {
	if (typeof text !== "string") throw new TypeError("text must be a string");
	return parse(text, 0, text.length);
}

